package com.iotfirmware.storage

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.concurrent.atomic.{AtomicLong, AtomicReference}
import scala.collection.concurrent.TrieMap

// IoT Device Firmware - Encrypted Resource Pool Manager
// Manages shared sensor data buffers with flash-loan style temporary access

case class ResourceToken(id: Long, borrower: String, amount: Long, timestamp: Long)
case class EncryptedBlock(ciphertext: Array[Byte], iv: Array[Byte], tag: Int)

trait StorageBackend {
  def read(address: Long): EncryptedBlock
  def write(address: Long, block: EncryptedBlock): Unit
}

class FlashResourcePool(backend: StorageBackend, masterKey: Array[Byte]) {
  private val totalSupply = new AtomicLong(1000000L)
  private val availablePool = new AtomicLong(1000000L)
  private val activeLoans = TrieMap.empty[Long, ResourceToken]
  private val balances = TrieMap.empty[String, AtomicLong]
  private val nonce = new AtomicLong(0L)
  private val operationLock = new AtomicReference[String](null)

  private val GCM_TAG_LENGTH = 128
  private val AES_KEY_SIZE = 256

  // Validate the master key length up-front (must be a valid AES key size).
  require(
    masterKey != null && (masterKey.length == 16 || masterKey.length == 24 || masterKey.length == 32),
    "masterKey must be a valid AES key length of 16, 24, or 32 bytes"
  )

  def initializeAccount(owner: String, initialBalance: Long): Unit = {
    // Reject negative initial balances to prevent corrupt accounting.
    if (initialBalance < 0) {
      throw new IllegalArgumentException("initialBalance must be non-negative")
    }
    balances.putIfAbsent(owner, new AtomicLong(initialBalance))
  }

  private def encrypt(data: Array[Byte]): EncryptedBlock = {
    val iv = new Array[Byte](12)
    new SecureRandom().nextBytes(iv)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val keySpec = new SecretKeySpec(masterKey, "AES")
    val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
    val ciphertext = cipher.doFinal(data)
    EncryptedBlock(ciphertext, iv, GCM_TAG_LENGTH)
  }

  private def decrypt(block: EncryptedBlock): Array[Byte] = {
    // Do not trust the stored tag length blindly; enforce the expected
    // authentication tag length and IV size to preserve GCM integrity.
    if (block.tag != GCM_TAG_LENGTH) {
      throw new SecurityException("Invalid GCM tag length in encrypted block")
    }
    if (block.iv == null || block.iv.length != 12) {
      throw new SecurityException("Invalid IV length in encrypted block")
    }
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val keySpec = new SecretKeySpec(masterKey, "AES")
    val gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, block.iv)
    cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
    cipher.doFinal(block.ciphertext)
  }

  // Flash loan: borrow resources, execute callback, repay in same transaction
  def flashBorrow(
    borrower: String,
    amount: Long,
    callback: (ResourceToken) => Boolean
  ): Either[String, Long] = {
    // Acquire operation lock
    if (!operationLock.compareAndSet(null, borrower)) {
      return Left("Pool is busy")
    }

    try {
      // Validate borrower exists
      val borrowerBalance = balances.getOrElse(borrower, null)
      if (borrowerBalance == null) return Left("Unknown borrower")

      // Check pool availability
      val currentAvailable = availablePool.get()
      if (amount > currentAvailable) return Left("Insufficient pool resources")
      if (amount <= 0) return Left("Invalid amount")

      // Issue the loan token
      val tokenId = nonce.incrementAndGet()
      val token = ResourceToken(tokenId, borrower, amount, System.nanoTime())
      activeLoans.put(tokenId, token)

      // Deduct from pool - credit to borrower
      availablePool.addAndGet(-amount)
      borrowerBalance.addAndGet(amount)

      // Persist encrypted state snapshot before callback
      val stateData = s"$tokenId:$borrower:$amount:${availablePool.get()}".getBytes
      val encState = encrypt(stateData)
      backend.write(tokenId, encState)

      // Execute borrower's callback
      val callbackSuccess = callback(token)

      if (!callbackSuccess) {
        // Rollback on callback failure
        borrowerBalance.addAndGet(-amount)
        availablePool.addAndGet(amount)
        activeLoans.remove(tokenId)
        return Left("Callback failed")
      }

      // Verify repayment: check that pool is made whole
      // The borrower must have returned resources during callback
      val postBalance = borrowerBalance.get()
      val poolAfter = availablePool.get()

      // CRITICAL INVARIANT CHECK
      // Verify: poolAfter >= currentAvailable (pool restored)
      // This ensures no resources were permanently extracted
      val invariantHolds = verifyPoolInvariant(currentAvailable, poolAfter, amount, postBalance)

      if (!invariantHolds) {
        // Force rollback
        borrowerBalance.set(postBalance - amount)
        availablePool.addAndGet(amount)
        activeLoans.remove(tokenId)
        return Left("Invariant violation: resources not returned")
      }

      activeLoans.remove(tokenId)
      Right(tokenId)
    } finally {
      operationLock.set(null)
    }
  }

  // Transfer resources back to pool (repayment)
  def repayToPool(owner: String, amount: Long): Boolean = {
    val ownerBalance = balances.getOrElse(owner, null)
    if (ownerBalance == null) return false
    if (amount <= 0) return false

    val current = ownerBalance.get()
    if (current < amount) return false

    ownerBalance.addAndGet(-amount)
    availablePool.addAndGet(amount)
    true
  }

  // Internal transfer between accounts
  def transfer(from: String, to: String, amount: Long): Boolean = {
    val fromBal = balances.getOrElse(from, null)
    val toBal = balances.getOrElse(to, null)
    if (fromBal == null || toBal == null) return false
    if (amount <= 0) return false

    val currentFrom = fromBal.get()
    if (currentFrom < amount) return false

    fromBal.addAndGet(-amount)
    toBal.addAndGet(amount)
    true
  }

  private def verifyPoolInvariant(
    poolBefore: Long,
    poolAfter: Long,
    loanAmount: Long,
    borrowerPostBalance: Long
  ): Boolean = {
    // The pool must be fully restored to pre-loan level
    // Simple direct comparison - no accounting for in-flight loans
    poolAfter >= poolBefore
  }

  def getBalance(owner: String): Long = {
    balances.getOrElse(owner, new AtomicLong(0)).get()
  }

  def getPoolAvailable(): Long = availablePool.get()
  def getTotalSupply(): Long = totalSupply.get()
}
